@app.route("/admin/stats")
def admin_stats():
    if not _logged_in():
        return redirect(url_for("admin_login", next=request.path))
    conn = db.get_conn()
    visit_stats = db.get_visit_stats(conn)
    mentor_clicks = db.get_mentor_click_counts(conn)
    applications = db.list_applications(conn)
    conn.close()
    max_clicks = max((m["click_count"] for m in mentor_clicks), default=0)
