        max_clicks=max_clicks, applications=applications,
    )


@app.route("/admin/applications/<int:application_id>/generate-link", methods=["POST"])
def admin_application_generate_link(application_id):
    """審核通過一筆申請後，建一筆空白草稿導師+專屬連結，教練複製後自己傳給申請人。"""
    if not _logged_in():
        return redirect(url_for("admin_login", next=request.path))
    conn = db.get_conn()
    application = db.get_application(conn, application_id)
    if not application:
        conn.close()
        abort(404)
    if not application["mentor_id"]:
        mentor_id, _token = db.create_draft_mentor(
            conn, application["name"], application["company"], DRAFT_PLACEHOLDER_PHOTO
        )
        db.link_application_mentor(conn, application_id, mentor_id)
    conn.close()
    return redirect(url_for("admin_stats"))


@app.route("/admin/mentors/new", methods=["GET", "POST"])
def admin_mentor_new():
    if not _logged_in():
        return redirect(url_for("admin_login", next=request.path))

    if request.method == "GET":
        return render_template("admin_form.html", mentor=None, error=None, form={})

    name = (request.form.get("name") or "").strip()
    company_title = (request.form.get("company_title") or "").strip()

    """回傳 True 代表確實有這位導師、寫入成功；mentor_id 不存在則回傳 False，不寫入。"""
    if not conn.execute("SELECT 1 FROM mentors WHERE id = ?", (mentor_id,)).fetchone():
        return False
    conn.execute("INSERT INTO mentor_clicks (mentor_id) VALUES (?)", (mentor_id,))
    conn.commit()
    return True


def insert_application(conn: sqlite3.Connection, name: str, company: str, line_id: str) -> None:
    conn.execute(
        "INSERT INTO applications (name, company, line_id) VALUES (?, ?, ?)",
        (name, company, line_id),
    )
    conn.commit()


def list_applications(conn: sqlite3.Connection):
    """帶出每筆申請對應的填寫連結(如果教練已經產生過)，沒產生過的a.mentor_id/edit_token/mentor_status會是None。"""
    return conn.execute("""
        SELECT a.*, m.edit_token AS edit_token, m.status AS mentor_status
        FROM applications a
        LEFT JOIN mentors m ON m.id = a.mentor_id
        ORDER BY a.id DESC
    """).fetchall()


def link_application_mentor(conn: sqlite3.Connection, application_id: int, mentor_id: int) -> None:
    conn.execute("UPDATE applications SET mentor_id = ? WHERE id = ?", (mentor_id, application_id))
    conn.commit()


def get_application(conn: sqlite3.Connection, application_id: int):
    return conn.execute("SELECT * FROM applications WHERE id = ?", (application_id,)).fetchone()


def get_total_views_since(conn: sqlite3.Connection, since: str) -> int:
    """熱度總造訪次數(含重複造訪)，只算某日期之後的，首頁公開計數器用。"""
    return conn.execute(
        "SELECT COUNT(*) FROM page_visits WHERE visited_at >= ?", (since,)
    ).fetchone()[0]

