def delete_application(conn: sqlite3.Connection, application_id: int) -> None:
    """刪除一筆申請(測試資料/重複送出)。若已產生填寫連結但還是草稿(尚未上架)，一併清掉那筆空白草稿導師；已上架的導師不動。"""
    application = get_application(conn, application_id)
    if application and application["mentor_id"]:
        mentor = conn.execute(
            "SELECT status FROM mentors WHERE id = ?", (application["mentor_id"],)
        ).fetchone()
        if mentor and mentor["status"] == "draft":
            conn.execute("DELETE FROM mentors WHERE id = ?", (application["mentor_id"],))
    conn.execute("DELETE FROM applications WHERE id = ?", (application_id,))
    conn.commit()

